<?php
namespace App\Interfaces\Http\Controllers\Api\V1\Reporting;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
final class InsuranceReportController{
public function portfolio(Request$r){$d=$r->validate(['from'=>'required|date','to'=>'required|date|after_or_equal:from','carrier_id'=>'nullable|uuid']);$tenant=app(\App\Domain\Tenancy\TenantContext::class)->id();$p=DB::table('policies')->where('tenant_id',$tenant)->whereBetween('created_at',[$d['from'],$d['to']]);if(!empty($d['carrier_id']))$p->where('carrier_id',$d['carrier_id']);$premium=(clone$p)->sum('premium_minor');$policies=(clone$p)->count();$active=(clone$p)->where('status','ACTIVE')->count();$claims=DB::table('claims')->where('tenant_id',$tenant)->whereBetween('created_at',[$d['from'],$d['to']]);$claimCount=(clone$claims)->count();$estimated=(clone$claims)->sum('estimated_loss_minor');return response()->json(['data'=>['period'=>$d,'policy_count'=>$policies,'active_policy_count'=>$active,'gross_written_premium_minor'=>(int)$premium,'claim_count'=>$claimCount,'estimated_loss_minor'=>(int)$estimated,'claim_frequency_basis_points'=>$policies?(int)round($claimCount*10000/$policies):0,'estimated_loss_ratio_basis_points'=>$premium?(int)round($estimated*10000/$premium):0,'currency'=>'XAF']]);}
public function renewals(Request$r){$tenant=app(\App\Domain\Tenancy\TenantContext::class)->id();return response()->json(['data'=>DB::table('renewal_work_items')->where('tenant_id',$tenant)->selectRaw('status, COUNT(*) as count')->groupBy('status')->get()]);}}
